const auditFactors = [
  {name:"Listing Verified & Live",section:"Profile basics",auto:true,meaning:"Confirms that the profile is verified, visible and eligible to appear in local results.",impact:"An unverified or hidden profile can lose visibility and customer trust.",action:"Confirm verification and check that the listing is publicly visible."},
  {name:"Business Name",section:"Profile basics",auto:true,meaning:"Checks whether the public business name is clear and matches the real-world brand.",impact:"An inaccurate name can create trust issues and increase the risk of profile problems.",action:"Use the real trading name consistently across the profile and signage."},
  {name:"Business Description",section:"Profile basics",auto:false,meaning:"Reviews whether the description explains the business, services and service area in plain language.",impact:"A weak description gives potential customers less reason to choose the business.",action:"Write a helpful, natural description covering the main services and local area."},
  {name:"Address",section:"Profile basics",auto:true,meaning:"Checks whether the address or service-area information is clear and appropriate.",impact:"Unclear location details can reduce local relevance and make visits or enquiries harder.",action:"Keep the address accurate, or clearly define the service areas when there is no storefront."},
  {name:"Phone Number",section:"Profile basics",auto:true,meaning:"Checks whether customers can find a direct, working contact number.",impact:"Missing or incorrect contact details can turn ready-to-buy searches into lost enquiries.",action:"Add a monitored local number and test it regularly."},
  {name:"Website Link",section:"Profile basics",auto:true,meaning:"Checks whether the profile sends visitors to a relevant business website or landing page.",impact:"Without a website, customers have fewer details and fewer ways to convert.",action:"Add a fast, mobile-friendly page that matches the service and location."},
  {name:"Appointment Link",section:"Profile basics",auto:false,meaning:"Checks whether customers can book, request a quote or schedule a service directly.",impact:"Extra steps can cause interested visitors to leave before making contact.",action:"Add a booking, quote or enquiry link when the business supports it."},
  {name:"Primary Category",section:"Profile basics",auto:false,meaning:"Checks whether the main category accurately describes the business’s core service.",impact:"The wrong category can show the business for irrelevant searches or hide it from valuable ones.",action:"Choose the most accurate primary category based on the main service offered."},
  {name:"Secondary Categories",section:"Profile basics",auto:false,meaning:"Checks whether additional relevant services are represented by suitable categories.",impact:"Missing categories can reduce visibility for related services customers actively search for.",action:"Add only relevant secondary categories that the business genuinely provides."},
  {name:"Opening Date",section:"Profile basics",auto:false,meaning:"Checks whether the profile communicates when the business started operating.",impact:"This can add context and reassurance, especially for customers comparing local providers.",action:"Add the correct opening date where the information is available."},
  {name:"Operating Hours",section:"Profile basics",auto:true,meaning:"Checks whether normal and special opening hours are complete and current.",impact:"Wrong hours create failed visits, missed calls and a poor customer experience.",action:"Update regular hours and special holiday hours before they change."},
  {name:"Payments Accepted",section:"Profile basics",auto:false,meaning:"Checks whether customers can understand the available payment methods.",impact:"Uncertainty at the point of purchase can delay or lose enquiries.",action:"List the main accepted payment methods when relevant to the service."},
  {name:"Services Added",section:"Profile basics",auto:false,meaning:"Checks whether the profile lists the individual services customers may need.",impact:"A short service list can make the business less relevant for specific searches.",action:"Add clear service names with useful descriptions and avoid keyword stuffing."},
  {name:"Services Areas Added",section:"Profile basics",auto:false,meaning:"Checks whether the towns, districts or areas served are clearly listed.",impact:"Customers may not know whether the business works in their location.",action:"Add accurate service areas that reflect where the business can actually operate."},
  {name:"Products Added",section:"Profile basics",auto:false,meaning:"Checks whether suitable products, packages or key offers are displayed.",impact:"Customers miss useful information that could help them compare and enquire.",action:"Add genuine products, packages or starting offers where appropriate."},
  {name:"NAP Added & Complete",section:"Profile basics",auto:true,meaning:"Checks consistency of the business name, address and phone details.",impact:"Inconsistent contact details can weaken trust and create confusion across local listings.",action:"Use the same accurate business details on the profile, website and important directories."},
  {name:"Attributes Added",section:"Profile basics",auto:false,meaning:"Checks whether helpful features such as accessibility, payment or business options are selected.",impact:"Missing attributes can prevent customers from knowing whether the business suits their needs.",action:"Complete only the attributes that are accurate and genuinely available."},
  {name:"Call History On",section:"Profile activity",auto:false,meaning:"Checks whether the profile’s call-history feature is enabled for tracking calls from Google.",impact:"Without it, it is harder to measure enquiries and identify missed opportunities.",action:"Review the owner dashboard and enable call history if it fits the business workflow."},
  {name:"Messaging On",section:"Profile activity",auto:false,meaning:"Checks whether customers can message the business from the profile.",impact:"Customers who prefer quick messages may choose a competitor with an easier contact option.",action:"Enable messaging only when someone can respond promptly and consistently."},
  {name:"Cover Photo",section:"Media",auto:false,meaning:"Checks whether the cover image presents the business professionally.",impact:"A poor or missing cover image can make the profile look unfinished.",action:"Use a clear, high-quality image that represents the service and location."},
  {name:"Profile Photo",section:"Media",auto:false,meaning:"Checks whether the profile has a recognisable logo or business image.",impact:"A missing profile image reduces recognition in Maps and search results.",action:"Add a sharp logo or consistent brand image that remains legible at small size."},
  {name:"General Photos",section:"Media",auto:true,meaning:"Checks whether the profile contains enough visual information about the business.",impact:"Customers often use photos to judge professionalism before contacting a provider.",action:"Build a balanced library showing the team, premises, work and customer experience."},
  {name:"Real Photos",section:"Media",auto:false,meaning:"Checks whether photos show genuine work, staff, premises or completed projects.",impact:"Stock-style or limited imagery provides less proof that the business is active and capable.",action:"Upload recent, original photos with permission and useful context."},
  {name:"Geo-Tagged",section:"Media",auto:false,meaning:"Checks whether the available photo-location evidence supports the stated service area.",impact:"Weak location evidence may reduce confidence in local relevance, although it is not a standalone ranking guarantee.",action:"Keep location and business details consistent; do not add artificial or misleading photo data."},
  {name:"Videos",section:"Media",auto:false,meaning:"Checks whether short videos demonstrate the service, team or customer experience.",impact:"Without video, the profile has fewer ways to show quality and build familiarity.",action:"Add simple, genuine videos of work, walkthroughs or frequently asked questions."},
  {name:"Photos Quantity",section:"Activity",auto:true,meaning:"Checks whether the profile has a healthy number of useful photos.",impact:"A very small photo library can make the business look inactive or difficult to evaluate.",action:"Add photos gradually and keep quality and relevance more important than volume."},
  {name:"Last Photo Uploaded",section:"Activity",auto:false,meaning:"Checks whether new photos have been added recently.",impact:"A long gap can make the profile appear less active than nearby competitors.",action:"Create a simple monthly photo routine using real updates and completed work."},
  {name:"Total Posts",section:"Activity",auto:false,meaning:"Checks whether the profile uses posts to share updates, offers, guidance or news.",impact:"Without posts, customers see less evidence of current activity and expertise.",action:"Publish useful updates connected to services, seasons, projects or common questions."},
  {name:"Last Post Date",section:"Activity",auto:false,meaning:"Checks how recently the business last published a profile post.",impact:"Outdated posts can reduce freshness and leave customers unsure what is current.",action:"Set a realistic posting schedule and remove or refresh expired offers."},
  {name:"Total Reviews",section:"Reviews",auto:true,meaning:"Checks the number of public customer reviews compared with the business and local market.",impact:"A small review footprint gives prospects less social proof when comparing providers.",action:"Ask genuine customers for honest feedback after completed work."},
  {name:"Last Review Date",section:"Reviews",auto:false,meaning:"Checks whether new customer reviews are arriving recently.",impact:"Recent reviews help show that the business is active and still serving customers.",action:"Use a consistent, policy-compliant review request process after service delivery."},
  {name:"Response Rate",section:"Reviews",auto:false,meaning:"Checks how consistently the business replies to customer reviews.",impact:"Unanswered reviews can make the business appear less engaged and reduce trust.",action:"Reply to reviews regularly with specific, polite and useful responses."},
  {name:"Last Response Date",section:"Reviews",auto:false,meaning:"Checks how recently the business last responded to a review.",impact:"A long response gap suggests that customer feedback may not be actively managed.",action:"Set a weekly reminder to review and respond to new feedback."},
  {name:"Negative Reviews Responded",section:"Reviews",auto:false,meaning:"Checks whether concerns in negative reviews receive a professional response.",impact:"Silence can leave future customers with only one side of the story.",action:"Acknowledge the concern, offer a next step and move private details offline."},
  {name:"% Negative Reviews Responded",section:"Reviews",auto:false,meaning:"Measures the share of negative reviews that received a response.",impact:"A low percentage can signal weak customer-care follow-through.",action:"Prioritise unresolved negative reviews while keeping every reply calm and factual."},
  {name:"% Positive Reviews Responded",section:"Reviews",auto:false,meaning:"Measures how often positive customer feedback is acknowledged.",impact:"Ignoring positive feedback misses a chance to strengthen relationships and brand trust.",action:"Thank customers naturally and mention the service detail they praised."},
  {name:"QnAs",section:"Engagement",auto:false,meaning:"Checks whether the profile’s questions and answers section is useful and maintained.",impact:"Unanswered questions can create uncertainty and send customers to competitors.",action:"Add accurate answers to common questions and monitor new customer questions."}
];

const storeKey = "gmbAuditLeadsV1";
let leads = loadLeads();
let activeLeadId = null;
const $ = (selector) => document.querySelector(selector);

function loadLeads(){try{return JSON.parse(localStorage.getItem(storeKey)||"[]")}catch{return[]}}
function saveLeads(){localStorage.setItem(storeKey,JSON.stringify(leads));renderAll()}
function id(){return crypto.randomUUID?crypto.randomUUID():String(Date.now())}
function initials(name){return (name||"?").split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function esc(value){return String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[c]))}
function scoreFor(lead){const values=Object.values(lead.audit||{});const counted=values.filter(x=>["Yes","No","Pass","Fail","Missing"].includes(x.status));if(!counted.length)return null;return Math.round(counted.filter(x=>["Yes","Pass"].includes(x.status)).length/counted.length*100)}
const proposalSettingsKey="gmbProposalSettingsV1";
function loadProposalSettings(){try{return JSON.parse(localStorage.getItem(proposalSettingsKey)||"{}")}catch{return{}}}
function saveProposalSettings(){const settings={agencyName:$("#agencyName")?.value.trim()||"",contactName:$("#contactName")?.value.trim()||"",email:$("#proposalEmail")?.value.trim()||"",phone:$("#proposalPhone")?.value.trim()||"",website:$("#proposalWebsite")?.value.trim()||""};localStorage.setItem(proposalSettingsKey,JSON.stringify(settings));showToast("Proposal details saved")}
function scoreClass(score){return score===null?"":score>=75?"good":score>=60?"mid":"low"}
function leadStatus(lead){const score=scoreFor(lead);if(score===null)return ["New","status-new"];if(lead.pipelineStatus==="Follow-up")return ["Follow-up","status-follow"];return ["Audited","status-audited"]}
function showToast(message){const toast=$("#toast");toast.textContent=message;toast.classList.add("show");clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove("show"),2600)}

function renderStats(){
  const scores=leads.map(scoreFor);$("#totalStat").textContent=leads.length;$("#auditedStat").textContent=scores.filter(x=>x!==null).length;$("#opportunityStat").textContent=scores.filter(x=>x!==null&&x<60).length;$("#followupStat").textContent=leads.filter(x=>x.pipelineStatus==="Follow-up").length;
}
function tableMarkup(items){
  if(!items.length)return `<div class="empty-state"><div class="empty-icon">⌕</div><strong>No prospects yet</strong><p>Start with a location and niche, or add a business manually.</p><button class="button button-primary" data-action="add">+ Add first business</button></div>`;
  return `<table class="lead-table"><thead><tr><th>Business</th><th>Location</th><th>Website</th><th>Audit score</th><th>Status</th><th>Action</th></tr></thead><tbody>${items.map(lead=>{const score=scoreFor(lead);const [status,cls]=leadStatus(lead);return `<tr><td><div class="business-cell"><div class="business-avatar">${esc(initials(lead.name))}</div><div><strong>${esc(lead.name)}</strong><span>${esc(lead.category||"Business profile")}</span></div></div></td><td>${esc(lead.address||lead.location||"—")}</td><td>${lead.website?`<a href="${esc(lead.website)}" target="_blank" rel="noreferrer">Open site</a>`:"—"}</td><td class="score ${scoreClass(score)}">${score===null?"—":score+"%"}</td><td><span class="status-tag ${cls}">${status}</span></td><td><div class="row-actions"><button class="mini-button" data-action="audit" data-id="${lead.id}">Audit</button><button class="mini-button" data-action="proposal" data-id="${lead.id}">Proposal</button><button class="mini-button" data-action="delete" data-id="${lead.id}">Delete</button></div></td></tr>`}).join("")}</tbody></table>`;
}
function renderTables(){
  $("#overviewTable").innerHTML=tableMarkup(leads.slice(0,6));
  const term=($("#leadFilter")?.value||"").toLowerCase();const filtered=leads.filter(x=>`${x.name} ${x.address} ${x.category}`.toLowerCase().includes(term));$("#prospectsTable").innerHTML=tableMarkup(filtered);
}
function renderChecklist(){
  $("#factorCount").textContent=`${auditFactors.length} client-friendly checks`;$("#checklistReference").innerHTML=auditFactors.map(x=>`<article class="check-item"><div class="check-item-main"><div class="check-item-title">${esc(x.name)}</div><p><strong>What it checks:</strong> ${esc(x.meaning)}</p><p class="check-impact"><strong>Business effect:</strong> ${esc(x.impact)}</p><p class="check-action"><strong>Recommended action:</strong> ${esc(x.action)}</p></div><span class="source-tag ${x.auto?"auto-tag":"manual-tag"}">${x.auto?"Public data":"Manual review"}</span></article>`).join("");
}
function renderAll(){renderStats();renderTables();renderChecklist()}

function switchView(view){document.querySelectorAll(".view").forEach(x=>x.classList.remove("active"));$("#"+view+"View")?.classList.add("active");document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.view===view))}
document.querySelectorAll(".nav-item").forEach(button=>button.addEventListener("click",()=>switchView(button.dataset.view)));
document.addEventListener("click",event=>{
  const viewTarget=event.target.closest("[data-view-target]");if(viewTarget)switchView(viewTarget.dataset.viewTarget);
  const action=event.target.closest("[data-action]");if(!action)return;const kind=action.dataset.action;if(kind==="add")openLeadModal();if(kind==="audit")openAuditModal(action.dataset.id);if(kind==="proposal")openProposalModal(action.dataset.id);if(kind==="delete")deleteLead(action.dataset.id);
});
$("#addLeadTop").addEventListener("click",openLeadModal);$("#leadFilter").addEventListener("input",renderTables);
const savedProposalSettings=loadProposalSettings();[["agencyName","agencyName"],["contactName","contactName"],["proposalEmail","email"],["proposalPhone","phone"],["proposalWebsite","website"]].forEach(([id,key])=>{if($("#"+id))$("#"+id).value=savedProposalSettings[key]||""});$("#saveProposalSettings").addEventListener("click",saveProposalSettings);
$("#modalClose").addEventListener("click",closeModal);$("#modalBackdrop").addEventListener("click",e=>{if(e.target.id==="modalBackdrop")closeModal()});

function openModal(content){$("#modalContent").innerHTML=content;$("#modalBackdrop").classList.remove("hidden")}
function closeModal(){$("#modalBackdrop").classList.add("hidden");$("#modalContent").innerHTML=""}
function openLeadModal(){openModal(`<span class="eyebrow accent">ADD PROSPECT</span><h2 id="modalTitle">Save a business</h2><p class="modal-subtitle">Add a profile now and complete its individual audit whenever you are ready.</p><form id="leadForm" class="modal-form"><label>Business name<input name="name" required placeholder="e.g. ABC Plumbing Ltd" /></label><label>Category<input name="category" placeholder="e.g. Plumber" /></label><label>Location/address<input name="address" placeholder="e.g. Birmingham, UK" /></label><label>Phone<input name="phone" placeholder="+44..." /></label><label class="full">Website URL<input name="website" type="url" placeholder="https://example.com" /></label><label class="full">Google Maps / Business Profile URL<input name="mapUrl" type="url" placeholder="https://maps.google.com/..." /></label><div class="modal-footer full"><button type="button" class="button button-secondary" id="cancelModal">Cancel</button><button class="button button-primary" type="submit">Save business</button></div></form>`);$("#cancelModal").addEventListener("click",closeModal);$("#leadForm").addEventListener("submit",e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));leads.unshift({id:id(),...data,createdAt:new Date().toISOString(),pipelineStatus:"New",audit:{}});saveLeads();closeModal();showToast("Business saved to your prospect list")})}

function openAuditModal(leadId){
  activeLeadId=leadId;const lead=leads.find(x=>x.id===leadId);if(!lead)return;const current=lead.audit||{};let lastSection="";
  const rows=auditFactors.map((factor,index)=>{let heading="";if(factor.section!==lastSection){lastSection=factor.section;heading=`<div class="audit-section">${esc(factor.section)}</div>`}const item=current[factor.name]||{status:"Not checked",notes:""};return `${heading}<div class="audit-row"><div class="audit-question"><div class="audit-factor-title">${esc(factor.name)}</div><p><strong>What it checks:</strong> ${esc(factor.meaning)}</p><p class="audit-impact"><strong>Business effect:</strong> ${esc(factor.impact)}</p><p class="audit-action"><strong>Recommended action:</strong> ${esc(factor.action)}</p></div><div class="audit-control"><label>Audit result<select data-factor="${esc(factor.name)}"><option value="Not checked" ${item.status==="Not checked"?"selected":""}>Not checked yet</option><option value="Yes" ${["Yes","Pass"].includes(item.status)?"selected":""}>Yes - Present / healthy</option><option value="No" ${["No","Fail","Missing"].includes(item.status)?"selected":""}>No - Needs attention</option></select></label></div><textarea data-note="${esc(factor.name)}" placeholder="Add evidence or a client note...">${esc(item.notes)}</textarea></div>`}).join("");
  openModal(`<span class="eyebrow accent">INDIVIDUAL AUDIT</span><h2 id="modalTitle">${esc(lead.name)}</h2><p class="modal-subtitle">${esc(lead.address||lead.location||"No location added")}</p><div class="audit-guide"><strong>How to answer</strong><span>Choose “Yes” when the item is present and working. Choose “No” when it is missing, weak or needs improvement.</span></div><div class="audit-summary"><div><span>Current score</span><strong id="liveScore">${scoreFor(lead)===null?"—":scoreFor(lead)+"%"}</strong></div><div><span>Checks completed</span><strong id="liveCount">${Object.values(current).filter(x=>x.status&&x.status!=="Not checked").length}/${auditFactors.length}</strong></div></div><div class="audit-list">${rows}</div><div class="modal-footer"><button class="button button-secondary" id="cancelAudit">Cancel</button><button class="button button-secondary" id="saveAuditProposal">Save & proposal</button><button class="button button-primary" id="saveAudit">Save audit</button></div>`);
  $("#cancelAudit").addEventListener("click",closeModal);document.querySelectorAll("[data-factor]").forEach(select=>select.addEventListener("change",updateLiveAudit));$("#saveAudit").addEventListener("click",saveAudit);$("#saveAuditProposal").addEventListener("click",()=>{saveAudit();setTimeout(()=>openProposalModal(leadId),0)});
}
function updateLiveAudit(){const entries=[...document.querySelectorAll("[data-factor]")];const counted=entries.filter(x=>["Yes","No"].includes(x.value));$("#liveCount").textContent=`${entries.filter(x=>x.value!=="Not checked").length}/${auditFactors.length}`;$("#liveScore").textContent=counted.length?Math.round(counted.filter(x=>x.value==="Yes").length/counted.length*100)+"%":"—"}
function saveAudit(){const lead=leads.find(x=>x.id===activeLeadId);if(!lead)return;const audit={};document.querySelectorAll("[data-factor]").forEach(select=>{const name=select.dataset.factor;const note=document.querySelector(`[data-note="${CSS.escape(name)}"]`).value;audit[name]={status:select.value,notes:note}});lead.audit=audit;lead.pipelineStatus="Audited";saveLeads();closeModal();showToast("Audit saved separately for this business")}
function normalizedStatus(status){if(["Pass","Yes"].includes(status))return "Yes";if(["Fail","Missing","No"].includes(status))return "No";return "Not checked"}
function proposalRows(lead){return auditFactors.map(factor=>{const item=lead.audit?.[factor.name]||{};return {name:factor.name,meaning:factor.meaning,impact:factor.impact,action:factor.action,status:normalizedStatus(item.status),notes:item.notes||""}})}
function proposalSummary(lead){const rows=proposalRows(lead);const yes=rows.filter(x=>x.status==="Yes");const no=rows.filter(x=>x.status==="No");const unchecked=rows.filter(x=>x.status==="Not checked");return {rows,yes,no,unchecked,score:scoreFor(lead)}}
function openProposalModal(leadId){const lead=leads.find(x=>x.id===leadId);if(!lead)return;const data=proposalSummary(lead);openModal(`<div class="proposal-preview"><span class="eyebrow accent">CLIENT PROPOSAL</span><h2 id="modalTitle">Local visibility proposal</h2><p class="modal-subtitle">${esc(lead.name)} · ${esc(lead.address||lead.location||"Location not added")}</p><div class="proposal-score"><div><span>Audit score</span><strong>${data.score===null?"—":data.score+"%"}</strong></div><div><span>Improvement opportunities</span><strong>${data.no.length}</strong></div><div><span>Checks completed</span><strong>${data.yes.length+data.no.length}/${auditFactors.length}</strong></div></div><div class="proposal-copy"><strong>Proposal preview</strong><p>We found ${data.no.length||"several"} areas that may be limiting ${esc(lead.name)}'s local visibility. Every checklist item in the exported report explains what it means, how it can affect the business and what action is recommended.</p></div><div class="proposal-actions"><button class="button button-secondary" id="cancelProposal">Close</button><button class="button button-primary" id="exportProposal">Export PDF</button></div></div>`);$("#cancelProposal").addEventListener("click",closeModal);$("#exportProposal").addEventListener("click",()=>printProposal(lead))}
function printProposal(lead){const settings=loadProposalSettings();const data=proposalSummary(lead);const preparedBy=settings.agencyName||settings.contactName||"Your Marketing Agency";const date=new Intl.DateTimeFormat(undefined,{year:"numeric",month:"long",day:"numeric"}).format(new Date());const issueList=data.no.length?data.no.slice(0,8).map(x=>`<li><strong>${esc(x.name)}</strong>${x.notes?`<span>${esc(x.notes)}</span>`:"<span>Needs improvement based on the audit response.</span>"}</li>`).join(""):"<li><strong>No negative responses recorded yet.</strong><span>Complete any remaining checks before sending the final proposal.</span></li>";const checklist=data.rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.meaning)}</td><td>${esc(x.impact)}</td><td>${esc(x.action)}</td><td><span class="pill ${x.status==="Yes"?"yes":x.status==="No"?"no":"pending"}">${x.status}</span></td><td>${esc(x.notes||"-")}</td></tr>`).join("");const win=window.open("","_blank");if(!win){showToast("Allow pop-ups to export the PDF");return}win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(lead.name)} - Local Visibility Proposal</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{margin:0;color:#182238;font:13px/1.55 Arial,Helvetica,sans-serif}h1,h2,h3,p{margin:0}h1{font-size:29px;line-height:1.15;letter-spacing:-.5px}h2{font-size:17px;margin-bottom:9px;color:#182238}h3{font-size:13px;margin-bottom:5px}.cover{background:#111a36;color:#fff;border-radius:12px;padding:28px 30px;margin-bottom:22px}.cover .eyebrow{color:#aaaaff;font-size:10px;font-weight:700;letter-spacing:2px}.cover h1{margin:11px 0 8px}.cover p{color:#d8def1}.meta{display:flex;justify-content:space-between;gap:16px;margin-top:23px;color:#d8def1;font-size:11px}.meta strong{display:block;color:#fff;font-size:13px;margin-top:2px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:18px 0 24px}.card{border:1px solid #e1e6ef;border-radius:9px;padding:13px}.card span{display:block;color:#6e7a8e;font-size:11px}.card strong{display:block;font-size:24px;margin-top:5px}.score{color:#138a62}.opportunity{color:#c33d4a}.pending{color:#b86b06}.section{margin:20px 0}.section p{color:#536177}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:24px}.issues{margin:0;padding:0;list-style:none}.issues li{border-left:3px solid #c33d4a;background:#fff5f6;padding:9px 11px;margin:8px 0}.issues strong,.issues span{display:block}.issues span{color:#647187;font-size:11px;margin-top:2px}.contact{background:#f4f6fb;border-radius:9px;padding:13px}.contact p{margin-top:4px;color:#536177}.contact a{color:#4338ca}.source{font-size:10px;color:#79859a;margin-top:22px}.page-break{page-break-before:always}table{width:100%;border-collapse:collapse;font-size:8px;line-height:1.35;table-layout:fixed}thead{display:table-header-group}th{text-align:left;text-transform:uppercase;letter-spacing:.45px;color:#758198;font-size:7.5px;padding:6px;border-bottom:1px solid #dfe5ee;background:#f4f6fb}td{padding:6px;border-bottom:1px solid #edf0f5;vertical-align:top;overflow-wrap:anywhere}td:nth-child(1){width:15%}td:nth-child(2){width:21%}td:nth-child(3){width:21%}td:nth-child(4){width:21%}td:nth-child(5){width:9%}td:nth-child(6){width:13%}.pill{display:inline-block;border-radius:99px;padding:2px 5px;font-size:8px;font-weight:700}.pill.yes{background:#e7f7ef;color:#138a62}.pill.no{background:#ffeaed;color:#c33d4a}.pill.pending{background:#fff3dc;color:#a66308}@media print{.cover{-webkit-print-color-adjust:exact;print-color-adjust:exact}.pill,.card,.issues li,th{ -webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><section class="cover"><div class="eyebrow">LOCAL SEARCH VISIBILITY PROPOSAL</div><h1>${esc(lead.name)}</h1><p>A practical improvement plan based on the current Google Business Profile audit.</p><div class="meta"><div>Prepared by<strong>${esc(preparedBy)}</strong></div><div>Report date<strong>${esc(date)}</strong></div></div></section><div class="cards"><div class="card"><span>Audit score</span><strong class="score">${data.score===null?"-":data.score+"%"}</strong></div><div class="card"><span>Improvement opportunities</span><strong class="opportunity">${data.no.length}</strong></div><div class="card"><span>Checks completed</span><strong>${data.yes.length+data.no.length}/${auditFactors.length}</strong></div></div><section class="section"><h2>Executive summary</h2><p>${data.no.length?`The audit identified ${data.no.length} improvement opportunities across the profile. Addressing these items can make the listing more complete, more trustworthy and more useful for local searchers.`:"The initial audit did not record any negative responses. Completing the remaining checks will help confirm the profile's full optimisation status."}</p></section><section class="section two-col"><div><h2>Recommended next steps</h2><ul class="issues">${issueList}</ul></div><div><h2>Business details</h2><div class="contact"><h3>${esc(lead.name)}</h3><p>${esc(lead.category||"Local business")}</p><p>${esc(lead.address||lead.location||"Address not added")}</p><p>${esc(lead.phone||"Phone not added")}</p>${lead.website?`<p><a href="${esc(lead.website)}">${esc(lead.website)}</a></p>`:""}${lead.mapUrl?`<p><a href="${esc(lead.mapUrl)}">View Google Maps listing</a></p>`:""}</div></div></section><p class="source">This report is based on the audit responses entered for this business. It is a proposal draft for discussion and should be confirmed against the live profile before delivery.</p><section class="page-break"><h2>Detailed audit checklist</h2><p class="source">Each item below explains the check in plain language, its possible business effect and the recommended action.</p><table><thead><tr><th>Audit factor</th><th>What it checks</th><th>Business effect</th><th>Recommended action</th><th>Status</th><th>Evidence / notes</th></tr></thead><tbody>${checklist}</tbody></table></section></body></html>`);win.document.close();setTimeout(()=>{win.focus();win.print()},300)}
function clientSectionName(section){return {"Profile basics":"Profile foundation","Profile activity":"Customer contact","Media":"Photos & media","Activity":"Freshness & activity","Reviews":"Reviews & reputation","Engagement":"Customer engagement"}[section]||section}
function clientSectionSummaries(rows){return [...new Set(auditFactors.map(x=>x.section))].map(section=>{const items=rows.filter(x=>auditFactors.find(f=>f.name===x.name)?.section===section);const checked=items.filter(x=>x.status!=="Not checked");const yes=checked.filter(x=>x.status==="Yes").length;return {name:clientSectionName(section),checked:checked.length,total:items.length,yes,no:checked.filter(x=>x.status==="No").length,score:checked.length?Math.round(yes/checked.length*100):null}})}
function proposalSummary(lead){const rows=proposalRows(lead);const yes=rows.filter(x=>x.status==="Yes");const no=rows.filter(x=>x.status==="No");const unchecked=rows.filter(x=>x.status==="Not checked");return {rows,yes,no,unchecked,score:scoreFor(lead),sections:clientSectionSummaries(rows)}}
function proposalScoreLabel(score){if(score===null)return "Audit not completed";if(score>=80)return "Strong profile foundation";if(score>=60)return "Good foundation with opportunities";return "High-priority opportunities identified"}
function openProposalModal(leadId){const lead=leads.find(x=>x.id===leadId);if(!lead)return;const data=proposalSummary(lead);const score=data.score===null?0:data.score;const findings=data.no.length?data.no.slice(0,6).map((x,index)=>`<article class="report-finding"><div class="finding-top"><span class="finding-number">0${index+1}</span><span class="priority-badge">Priority ${index+1}</span></div><h3>${esc(x.name)}</h3><p>${esc(x.impact)}</p><div class="finding-action"><strong>Recommended next step</strong><span>${esc(x.action)}</span></div></article>`).join(""):"<div class=\"report-empty\"><strong>No negative responses recorded yet.</strong><span>Complete the remaining audit checks to generate client recommendations.</span></div>";const categories=data.sections.map(x=>`<div class="category-score"><div class="category-score-head"><strong>${esc(x.name)}</strong><span>${x.score===null?"Not checked":x.score+"%"}</span></div><div class="category-bar"><i style="width:${x.score===null?0:x.score}%"></i></div><small>${x.checked}/${x.total} checks completed · ${x.no} needing attention</small></div>`).join("");openModal(`<div class="report-preview"><div class="report-head"><div><span class="eyebrow accent">CLIENT REPORT</span><h2 id="modalTitle">Local visibility snapshot</h2><p class="modal-subtitle">${esc(lead.name)} · ${esc(lead.address||lead.location||"Location not added")}</p></div><span class="report-draft">Audit summary</span></div><div class="report-hero"><div class="score-ring" style="--score:${score}"><div><strong>${data.score===null?"-":data.score+"%"}</strong><span>Profile health</span></div></div><div class="report-hero-copy"><span class="report-kicker">OVERALL FINDING</span><h3>${proposalScoreLabel(data.score)}</h3><p>${data.no.length?`We found ${data.no.length} areas that may be limiting how confidently local customers can find, understand and contact this business.`:"The audit is ready for review. Complete the checks to turn this snapshot into a focused action plan."}</p></div></div><div class="report-kpi-grid"><div><span>Improvement opportunities</span><strong>${data.no.length}</strong><small>Prioritised below</small></div><div><span>Checks completed</span><strong>${data.yes.length+data.no.length}/${auditFactors.length}</strong><small>${data.unchecked.length?data.unchecked.length+" still to review":"Full checklist reviewed"}</small></div><div><span>Report focus</span><strong>Action</strong><small>What to fix next</small></div></div><section class="report-block"><div class="report-block-title"><div><span class="eyebrow">WHAT WE FOUND</span><h3>Top opportunities for this business</h3></div><span class="report-count">${data.no.length} findings</span></div><div class="report-findings">${findings}</div></section><section class="report-block"><div class="report-block-title"><div><span class="eyebrow">PROFILE HEALTH</span><h3>How each area is performing</h3></div></div><div class="category-grid">${categories}</div></section><section class="report-plan"><div><span class="eyebrow">RECOMMENDED PLAN</span><h3>Turn the findings into visible improvements</h3></div><div class="plan-grid"><div><span>01</span><strong>Fix the foundations</strong><p>Complete categories, services, contact details, hours and service areas.</p></div><div><span>02</span><strong>Improve trust and conversion</strong><p>Strengthen the website link, photos, booking options and review responses.</p></div><div><span>03</span><strong>Keep the profile active</strong><p>Use posts, new project photos, customer questions and regular review replies.</p></div></div></section><div class="report-note"><strong>This report is written for decision-making.</strong><span>The detailed checklist and evidence stay available in the exported PDF appendix.</span></div><div class="proposal-actions"><button class="button button-secondary" id="cancelProposal">Close</button><button class="button button-primary" id="exportProposal">Export client PDF</button></div></div>`);$("#cancelProposal").addEventListener("click",closeModal);$("#exportProposal").addEventListener("click",()=>printProposal(lead))}
function printProposal(lead){const settings=loadProposalSettings();const data=proposalSummary(lead);const preparedBy=settings.agencyName||settings.contactName||"Your Marketing Agency";const date=new Intl.DateTimeFormat(undefined,{year:"numeric",month:"long",day:"numeric"}).format(new Date());const score=data.score===null?0:data.score;const findings=data.no.length?data.no.slice(0,6).map((x,index)=>`<div class="finding"><div class="finding-meta"><span>0${index+1}</span><b>Priority ${index+1}</b></div><h3>${esc(x.name)}</h3><p>${esc(x.impact)}</p><div class="recommend"><strong>Recommended next step</strong><span>${esc(x.action)}</span></div></div>`).join(""):"<div class=\"empty\"><strong>No negative responses recorded yet.</strong><span>Complete the remaining checks before sending the final report.</span></div>";const categories=data.sections.map(x=>`<div class="category"><div><strong>${esc(x.name)}</strong><b>${x.score===null?"-":x.score+"%"}</b></div><i><em style="width:${x.score===null?0:x.score}%"></em></i><small>${x.checked}/${x.total} checks complete</small></div>`).join("");const appendix=data.rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td><span class="pill ${x.status==="Yes"?"yes":x.status==="No"?"no":"pending"}">${x.status}</span></td><td>${esc(x.notes||"No evidence note added")}</td></tr>`).join("");const win=window.open("","_blank");if(!win){showToast("Allow pop-ups to export the PDF");return}win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(lead.name)} - Local Visibility Report</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{margin:0;color:#17213a;font:13px/1.5 Arial,Helvetica,sans-serif}h1,h2,h3,p{margin:0}h1{font-size:30px;line-height:1.1;letter-spacing:-.7px}h2{font-size:20px;line-height:1.2;margin-bottom:5px}h3{font-size:15px;line-height:1.25;margin-bottom:6px}.eyebrow{font-size:9px;font-weight:800;letter-spacing:1.8px;color:#5b54d6}.cover{background:#111a36;color:#fff;border-radius:13px;padding:31px 32px 28px;margin-bottom:18px}.cover .eyebrow{color:#aaaaff}.cover h1{margin:12px 0 8px}.cover p{color:#d8def1;font-size:13px}.meta{display:flex;justify-content:space-between;gap:20px;margin-top:27px;color:#b9c2d8;font-size:10px}.meta strong{display:block;color:#fff;font-size:12px;margin-top:3px}.kpi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:0 0 18px}.kpi{border:1px solid #e1e6ef;border-radius:9px;padding:12px}.kpi span,.kpi small{display:block;color:#718099;font-size:10px}.kpi strong{display:block;font-size:23px;margin:3px 0}.kpi.score strong{color:#138a62}.kpi.opportunity strong{color:#c33d4a}.intro{color:#536177;margin:0 0 18px}.two-col{display:grid;grid-template-columns:1.25fr .75fr;gap:18px;align-items:start}.block{margin:0 0 17px}.block h2{font-size:17px}.findings{display:grid;gap:8px}.finding{border:1px solid #e1e6ef;border-left:3px solid #c33d4a;border-radius:8px;padding:9px 11px}.finding-meta{display:flex;justify-content:space-between;align-items:center;color:#9b4a52;font-size:9px;text-transform:uppercase;letter-spacing:.5px}.finding-meta span{background:#ffeaed;border-radius:99px;padding:2px 6px;font-weight:700}.finding h3{font-size:12px;margin:6px 0 3px}.finding p{color:#536177;font-size:10px}.recommend{background:#f5f7fb;border-radius:5px;padding:6px 7px;margin-top:6px}.recommend strong,.recommend span{display:block}.recommend strong{font-size:9px;color:#536177}.recommend span{font-size:10px;color:#182238;margin-top:2px}.categories{display:grid;gap:9px}.category{border:1px solid #e1e6ef;border-radius:8px;padding:9px}.category>div{display:flex;justify-content:space-between;font-size:11px}.category b{color:#138a62}.category i{display:block;height:5px;background:#edf0f5;border-radius:99px;margin:7px 0 4px;overflow:hidden}.category em{display:block;height:100%;background:#5b54d6;border-radius:99px}.category small{color:#718099;font-size:9px}.plan{background:#eef0ff;border-radius:10px;padding:13px;margin-top:2px}.plan h2{font-size:17px}.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:10px}.plan-card{background:#fff;border-radius:7px;padding:9px}.plan-card span{color:#5b54d6;font-weight:800;font-size:10px}.plan-card strong{display:block;font-size:11px;margin:3px 0}.plan-card p{color:#536177;font-size:9px}.note{font-size:9px;color:#79859a;margin-top:13px}.page-break{page-break-before:always}.appendix-intro{color:#536177;margin-bottom:12px}table{width:100%;border-collapse:collapse;font-size:10px}th{text-align:left;text-transform:uppercase;letter-spacing:.6px;color:#758198;font-size:8px;padding:7px;background:#f4f6fb;border-bottom:1px solid #dfe5ee}td{padding:7px;border-bottom:1px solid #edf0f5;vertical-align:top}td:nth-child(1){width:38%}td:nth-child(2){width:18%}.pill{display:inline-block;border-radius:99px;padding:2px 7px;font-size:8px;font-weight:700}.pill.yes{background:#e7f7ef;color:#138a62}.pill.no{background:#ffeaed;color:#c33d4a}.pill.pending{background:#fff3dc;color:#a66308}.footer{display:flex;justify-content:space-between;border-top:1px solid #dfe5ee;margin-top:22px;padding-top:8px;color:#7a869b;font-size:9px}@media print{.cover,.plan,.kpi,.finding,.pill,th{ -webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><section class="cover"><div class="eyebrow">LOCAL SEARCH VISIBILITY REPORT</div><h1>${esc(lead.name)}</h1><p>A clear snapshot of the profile health, customer impact and recommended next actions.</p><div class="meta"><div>Prepared by<strong>${esc(preparedBy)}</strong></div><div>Report date<strong>${esc(date)}</strong></div></div></section><div class="kpi-grid"><div class="kpi score"><span>Profile health</span><strong>${data.score===null?"-":data.score+"%"}</strong><small>${data.score===null?"Audit not completed":proposalScoreLabel(data.score)}</small></div><div class="kpi opportunity"><span>Improvement opportunities</span><strong>${data.no.length}</strong><small>Prioritised for action</small></div><div class="kpi"><span>Checks completed</span><strong>${data.yes.length+data.no.length}/${auditFactors.length}</strong><small>${esc(lead.address||lead.location||"Location not added")}</small></div></div><p class="intro">This report translates the Google Business Profile audit into practical business decisions. It highlights the areas most likely to affect visibility, trust and customer enquiries.</p><div class="two-col"><section class="block"><h2>Top opportunities</h2><div class="findings">${findings}</div></section><section class="block"><h2>Profile health by area</h2><div class="categories">${categories}</div></section></div><section class="plan"><h2>Recommended improvement plan</h2><p class="intro">The work can be handled in three connected stages, starting with the items that improve clarity and conversion.</p><div class="plan-grid"><div class="plan-card"><span>01</span><strong>Fix the foundations</strong><p>Complete categories, services, contact details, hours and service areas.</p></div><div class="plan-card"><span>02</span><strong>Improve trust and conversion</strong><p>Strengthen website, photos, booking options and review responses.</p></div><div class="plan-card"><span>03</span><strong>Keep the profile active</strong><p>Use posts, project photos, customer questions and regular review replies.</p></div></div></section><p class="note">This report is based on the audit responses entered for this business. Recommendations should be confirmed against the live profile before delivery.</p><div class="footer"><span>${esc(preparedBy)} · Confidential client report</span><span>Page 1</span></div><section class="page-break"><h2>Audit evidence appendix</h2><p class="appendix-intro">This appendix preserves the full audit record behind the summary. It is included for transparency and future follow-up.</p><table><thead><tr><th>Audit factor</th><th>Status</th><th>Evidence / notes</th></tr></thead><tbody>${appendix}</tbody></table><div class="footer"><span>${esc(preparedBy)} · Detailed audit appendix</span><span>Audit record</span></div></section></body></html>`);win.document.close();setTimeout(()=>{win.focus();win.print()},300)}
function deleteLead(leadId){const lead=leads.find(x=>x.id===leadId);if(!lead)return;if(!confirm(`Delete ${lead.name}?`))return;leads=leads.filter(x=>x.id!==leadId);saveLeads();showToast("Business removed")}

$("#searchForm").addEventListener("submit",async e=>{e.preventDefault();const location=$("#locationInput").value.trim();const niche=$("#nicheInput").value.trim();const keyword=$("#keywordInput").value.trim()||niche;const radius=$("#radiusInput").value;const notice=$("#searchNotice");notice.classList.remove("hidden");notice.className="notice";notice.textContent="Searching public business profiles...";try{const response=await fetch("/api/search-businesses",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({location,niche,keyword,radius})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Search failed");const existing=new Set(leads.map(x=>x.id));const fresh=data.businesses.filter(x=>!existing.has(x.id));leads=[...fresh,...leads];saveLeads();notice.innerHTML=`<strong>${data.count} profiles found.</strong> ${fresh.length} new businesses were added. Each profile now has its own audit record.`;showToast(`${fresh.length} new prospects added`)}catch(error){notice.className="notice";notice.innerHTML=`<strong>Live search is not connected yet.</strong> ${esc(error.message)} Add <b>GOOGLE_MAPS_API_KEY</b> in Netlify environment variables, then run the search again.`}switchView("overview")});
$("#mapsImportForm").addEventListener("submit",async e=>{e.preventDefault();const input=$("#mapsLinksInput");const notice=$("#importNotice");const links=[...new Set(input.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];if(!links.length){notice.className="notice";notice.textContent="Paste at least one Google Maps link, one per line.";return}notice.className="notice";notice.textContent=`Importing ${links.length} link${links.length===1?"":"s"}...`;try{const response=await fetch("/api/import-maps-links",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({links})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Import failed");const existing=new Set(leads.map(x=>x.mapUrl).filter(Boolean));const fresh=data.businesses.filter(x=>!existing.has(x.mapUrl));leads=[...fresh,...leads];saveLeads();input.value="";const rejected=data.rejected?.length?` ${data.rejected.length} link${data.rejected.length===1?"":"s"} could not be accepted.`:"";notice.innerHTML=`<strong>${fresh.length} new prospect${fresh.length===1?"":"s"} added.</strong> Publicly available details were imported; open each audit for the remaining checks.${rejected}`;showToast(`${fresh.length} map link${fresh.length===1?"":"s"} imported`)}catch(error){notice.className="notice";notice.innerHTML=`<strong>Import failed.</strong> ${esc(error.message)} Try a full Google Maps listing URL.`}});
$("#exportCsv").addEventListener("click",()=>{if(!leads.length){showToast("There are no prospects to export yet");return}const headers=["Business","Category","Address","Phone","Website","Maps URL","Audit Score","Status"];const lines=[headers,...leads.map(x=>{const score=scoreFor(x);return[x.name,x.category,x.address,x.phone,x.website,x.mapUrl,score===null?"":score,leadStatus(x)[0]]})].map(row=>row.map(value=>`"${String(value??"").replace(/"/g,'""')}"`).join(","));const blob=new Blob([lines.join("\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="gmb-prospects.csv";a.click();URL.revokeObjectURL(url);showToast("CSV exported")});
renderAll();
